MultiLanguageSpellData['de'][163988] = {name = "Arkaner Zorn: Verschiebung", additional_info = "Wirken in 1.5 sek.\n[q]Kaiser Mar'gok trifft einen zufälligen Spielercharakter mit arkaner Energie, die ihn 4 Sek. lang brandmarkt.\n\n Wenn das Brandmal ausläuft, fügt es dem Träger 3591 Arkanschaden zu und springt zum nächsten Verbündeten innerhalb von 200 Metern.\n\n Jedes Mal, wenn 'Arkaner Zorn' springt, nimmt der Schaden um 25% zu und die Reichweite um 50% ab.\n\n Verschiebung: Gebrandmarkte Spielercharaktere können sich nicht mehr als 10 Meter vom Ort entfernen, an dem 'Gebrandmarkt' angewendet wurde."}
MultiLanguageSpellData['de'][163989] = {name = "Arkaner Zorn: Stärkung", additional_info = "Wirken in 1.5 sek.\n[q]Kaiser Mar'gok trifft einen zufälligen Spielercharakter mit arkaner Energie, die ihn 4 Sek. lang brandmarkt.\n\n Wenn das Brandmal ausläuft, fügt es dem Träger 3591 Arkanschaden zu und springt zum nächsten Verbündeten innerhalb von 200 Metern.\n\n Jedes Mal, wenn 'Arkaner Zorn' springt, nimmt der Schaden um 25% zu und die Reichweite um 25% ab.\n\n Stärkung: Die Sprungreichweite von 'Arkaner Zorn' verringert sich mit jedem Sprung nur um 25%."}
MultiLanguageSpellData['de'][163990] = {name = "Arkaner Zorn: Reproduktion", additional_info = "Wirken in 1.5 sek.\n[q]Kaiser Mar'gok trifft einen zufälligen Spielercharakter mit arkaner Energie, die ihn 4 Sek. lang brandmarkt.\n\n Wenn das Brandmal ausläuft, fügt es dem Träger 3591 Arkanschaden zu und springt zum nächsten Verbündeten innerhalb von 200 Metern über.\n\n Jedes Mal, wenn 'Arkaner Zorn' überspringt, nimmt der Schaden um 25% zu und die Reichweite um 50% ab.\n\n Reproduktion: 'Arkaner Zorn' springt beim ersten Sprung auf zwei zufällige Ziele über und brandmarkt beide."}
