MultiLanguageSpellData['de'][164065] = {name = "Antimagisches Feld", additional_info = "1 Rune / -10 Runenmacht\nSofort\n[q]Platziert ein großes, ortsgebundenes antimagisches Feld, das den erlittenen Zauberschaden aller darin befindlichen Gruppen- oder Schlachtzugsmitglieder um 49% verringert. Das antimagische Feld hält 6 Sek. lang an oder bis es (0 + 2 * Angriffskraft) Zauberschaden absorbiert hat."}
MultiLanguageSpellData['de'][164066] = {name = "Totenerweckung", additional_info = "30 Meter Reichweite\nSofort\n[q]Erweckt einen Ghul, der an Eurer Seite kämpft. Steht kein humanoider Leichnam zur Verfügung, der Erfahrung oder Ehre gewährt, wird Leichenstaub benötigt, um den Zauber zu wirken. Ihr könnt nur maximal einen Ghul gleichzeitig beschwören. Hält 1 Min. lang."}
MultiLanguageSpellData['de'][164067] = {name = "Frostnova", additional_info = "75 Mana\nSofort\n[q]Fügt Gegnern in der Nähe Frostschaden zu und macht sie bis zu 8 Sek. lang bewegungsunfähig."}
MultiLanguageSpellData['de'][164068] = {name = "Frostrüstung", additional_info = "{Sofort} {10 sek. Abklingzeit}\n[q]Umgibt den Zaubernden mit einer Frostschicht, die 30 Min. lang bestehen bleibt. Das dicke Eis erhöht die Rüstung, verringert die Bewegungsgeschwindigkeit von Nahkampfangreifern und erhöht die Zeit zwischen ihren Angriffen."}
