MultiLanguageSpellData['de'][164072] = {name = "Elektroschmettern", additional_info = "2 Meter Reichweite\nSofort\n[q]Kracht mit vollem Gewicht auf den Boden, was allen Gegnern im Umkreis von 10 Metern um den Einschlagspunkt Naturschaden zufügt."}
MultiLanguageSpellData['de'][164073] = {name = "Elektroschmettern", additional_info = "8 - 40 Meter Reichweite\nSofort\n[q]Hüpft in die Luft und kracht mit voller Wucht herunter, was allen Gegnern im Umkreis von 2 Metern um den Einschlagspunkt körperlichen Schaden zufügt und sie zurückstößt."}
MultiLanguageSpellData['de'][164074] = {name = "Destruktive Resonanz", additional_info = "Sofort"}
MultiLanguageSpellData['de'][164075] = {name = "Destruktive Resonanz: Verschiebung", additional_info = "Wirken in 1.5 sek.\n[q]Kaiser Mar'gok beschwört eine arkane Mine unter einem zufälligen Gegner, die sich nach 3 Sek. scharf macht. Die Mine bleibt 1 Min. bestehen und wird von jedem Spielercharakter ausgelöst, der ihren Radius nach dem Scharfmachen betritt.\n\n Bei Auslösung explodiert 'Destruktive Resonanz', fügt allen Spielercharakteren in ihrem Radius 9019 Arkanschaden zu und erhöht deren erlittenen Arkanschaden 1 Min. lang um 45%.\n\n Verlagerung: 'Destruktive Resonanz' wächst innerhalb von 30 Sek. auf das Doppelte ihrer ursprünglichen Größe an."}
MultiLanguageSpellData['de'][164076] = {name = "Destruktive Resonanz: Stärkung", additional_info = "Wirken in 1.5 sek.\n[q]Kaiser Mar'gok beschwört eine arkane Mine unter einem zufälligen Gegner, die nach 3 Sek. scharf ist. Die scharfe Mine bleibt 2 Min. bestehen und wird von jedem Spielercharakter ausgelöst, der ihren Radius nach dem Scharfmachen betritt.\n\n Wird die Mine ausgelöst, explodiert 'Destruktive Resonanz', fügt allen Spielercharakteren in ihrem Radius 9019 Arkanschaden zu und erhöht deren erlittenen Arkanschaden 1 Min. lang um 45%.\n\n Stärkung: 'Destruktive Resonanz' hält 2 Min. lang an."}
MultiLanguageSpellData['de'][164077] = {name = "Destruktive Resonanz: Reproduktion", additional_info = "Wirken in 1.5 sek.\n[q]Kaiser Mar'gok beschwört eine arkane Mine unter einem zufälligen Gegner, die nach 3 Sek. scharf ist. Die scharfe Mine bleibt 1 Min. bestehen und wird von jedem Spielercharakter ausgelöst, der ihren Radius nach dem Scharfmachen betritt.\n\n Wird die Mine ausgelöst, explodiert 'Destruktive Resonanz', fügt allen Spielercharakteren in ihrem Radius 9019 Arkanschaden zu und erhöht deren erlittenen Arkanschaden 1 Min. lang um 45%.\n\n Reproduktion: Wenn 'Destruktive Resonanz' explodiert oder ausläuft, werden zwei weitere 'destruktive Resonanzen in der Nähe platziert."}
MultiLanguageSpellData['de'][164078] = {name = "Hydrauliktritt", additional_info = "8 Meter Reichweite\n{Sofort} {1 sek. Abklingzeit}\n[q]Tritt dem Gegner ins Gesicht, fügt ihm 0 körperlichen Schaden zu, entfernt sämtliche Bedrohung und stößt ihn zurück."}
