MultiLanguageSpellData['de'][165722] = {name = "Blutdurst", additional_info = "Nahkampfreichweite\n{Sofort} {10 sek. Abklingzeit}\nBenötigt Nahkampfwaffe\n[q]Greift das Ziel sofort an und verursacht 120% normalen Waffenschaden. Außredem stellen erfolgreiche Nahkampfangriffe 1% der maximalen Gesundheit wieder her. Der Effekt hält 10 Sek. lang an."}
MultiLanguageSpellData['de'][165723] = {name = "Schlachtruf", additional_info = "Sofort\n[q]Erhöht 2 Min. lang die Nahkampfangriffskraft verbündeter Ziele in der Nähe."}
MultiLanguageSpellData['de'][165724] = {name = "Kriegsmaschinen zum Schweigen bringen: Eiserne Kriegsmaschine beschwören - Horde", additional_info = nil}
MultiLanguageSpellData['de'][165725] = {name = "Schlitzer beschwören", additional_info = nil}
MultiLanguageSpellData['de'][165727] = {name = "Garrison - Attack - Goren Spawn in, Pre-, Attack Guard", additional_info = nil}
MultiLanguageSpellData['de'][165728] = {name = "Garnisonsspezialisierung erlernen: Minenwache", additional_info = "Wirken in 3 sek.\n[q]Schaltet die Minenwachespezialisierung für die Garnisonsmine frei."}
MultiLanguageSpellData['de'][165729] = {name = "Anhängerin: Kaz die Kreischende", additional_info = "Sofort\n[q]Kaz die Kreischende ist für ihre Brutalität und ihre Vorliebe für brennende Dinge bekannt. Ungeachtet ihres Wahnsinns ist sie eine mächtige Schamanin."}
MultiLanguageSpellData['de'][165730] = {name = "Erlernen", additional_info = "Wirken in 3 sek.\n[q]Gewährt Pläne, mit denen Ihr in Eurer Garnison eine Mondsturzausgrabung bauen könnt.\n\n Level 1\nErmöglicht Spielercharakteren, draenische Steine aus Mineraladern in Draenor zu fördern. Draenische Steine können in Arbeitsaufträge für Draenormineralien umgewandelt werden.\n\n Level 2\nBergbauanhänger können hier arbeiten, was einen einzigartigen Bonus gewährt. Außerdem enthält ein neuer Grubenschacht weitere Adern und ermöglicht bis zu 14 Arbeitsaufträge gleichzeitig.\n\n Level 3\nEin letzter Grubenschacht ermöglicht den Zugang zu reichen Erzadern. Zusätzlich patrouillieren Garnisonswachen in der Mine und halten angriffslustige Goren fern. Ermöglicht außerdem bis zu 21 Arbeitsaufträge gleichzeitig."}
MultiLanguageSpellData['de'][165731] = {name = "Durchbohrender Ansturm", additional_info = "100 Meter Reichweite\nSofort\n[q]Der Zaubernde sammelt Kraft für einen mächtigen Schlag gegen das aktuelle Ziel und fügt allen, die vom Schlag erfasst werden, schweren körperlichen Schaden zu."}
MultiLanguageSpellData['de'][165732] = {name = "Durchbohrender Ansturm", additional_info = "20 Meter Reichweite\nSofort\n[q]Der Zaubernde sammelt Kraft für einen mächtigen Schlag gegen das aktuelle Ziel und fügt allen, die vom Schlag erfasst werden, schweren körperlichen Schaden zu."}
MultiLanguageSpellData['de'][165733] = {name = "Durchbohrender Ansturm", additional_info = "100 Meter Reichweite\n{Sofort} {8 sek. Abklingzeit}\n[q]Der Zaubernde sammelt Kraft für einen mächtigen Schlag gegen das aktuelle Ziel und fügt allen, die vom Schlag erfasst werden, schweren körperlichen Schaden zu."}
MultiLanguageSpellData['de'][165735] = {name = "Teufelsrüstung", additional_info = "28% von Grundmana\nSofort\n[q]Umgibt Euch mit Teufelsenergie, die Eure Zaubermacht um 10% erhöht. Zusätzlich regeneriert Ihr alle 5 Sek. 2% Eurer gesamten Gesundheit. Es kann immer nur eine Art Rüstungszauber gleichzeitig aktiv sein. Hält 30 Min. lang an."}
MultiLanguageSpellData['de'][165736] = {name = "Wichtel beschwören", additional_info = "Sofort\n[q]Beschwört einen Wichtel, der den Zaubernden bis zur Freigabe begleitet."}
MultiLanguageSpellData['de'][165737] = {name = "Erneuerung", additional_info = "{90 Mana} {40 Meter Reichweite}\nSofort\n[q]Heilt einen Verbündeten 15 Sek. lang alle 3 Sek."}
MultiLanguageSpellData['de'][165738] = {name = "Heilige Nova", additional_info = "15 Mana\nSofort\n[q]Verursacht eine Explosion heiligen Lichts um den Zaubernden herum und fügt allen Zielen in einem Umkreis von 10 Metern 147 Heiligschaden zu. Zusätzlich werden alle Gruppenmitglieder in einem Umkreis von 10 Metern um 3 geheilt. Dieser Effekt erzeugt keine Bedrohung."}
MultiLanguageSpellData['de'][165739] = {name = "Machtwort: Seelenstärke", additional_info = "30 Meter Reichweite\nSofort\n[q]Erfüllt das Ziel mit Lebenskraft, die seine Ausdauer 1 Stunde lang um 10% erhöht.\n\n Wenn sich das Ziel in Eurer Gruppe oder Eurem Schlachtzug befindet, werden alle Mitglieder den Effekt erhalten."}
MultiLanguageSpellData['de'][165740] = {name = "Heulende Böe", additional_info = "20 Meter Reichweite\nWirken in 1.5 sek.\n[q]Weht dem Ziel eine eisige Böe entgegen, die allen Zielen innerhalb von 10 Metern Frostschaden zufügt. Gefrorene Ziele erleiden dreifachen Schaden."}
MultiLanguageSpellData['de'][165741] = {name = "Frostnova", additional_info = "30 Mana\nWirken in 2 sek.\n[q]Fügt Gegnern in der Nähe Frostschaden zu und macht sie bis zu 4 Sek. lang bewegungsunfähig."}
MultiLanguageSpellData['de'][165742] = {name = "Blizzard", additional_info = "{35 Mana} {30 Meter Reichweite}\nWirken in 2 sek.\n[q]Ruft einen Blizzard herbei, der 8 Sek. lang anhält und Gegnern im Zielgebiet alle 2 Sek. Frostschaden zufügt."}
MultiLanguageSpellData['de'][165743] = {name = "Frostrüstung", additional_info = "{Sofort} {10 sek. Abklingzeit}\n[q]Umgibt den Zaubernden mit einer Frostschicht, die 30 Min. lang bestehen bleibt. Das dicke Eis erhöht die Rüstung, verringert die Bewegungsgeschwindigkeit von Nahkampfangreifern und erhöht die Zeit zwischen ihren Angriffen."}
MultiLanguageSpellData['de'][165744] = {name = "Göttlicher Sturm", additional_info = "{20% von Grundmana} {Nahkampfreichweite}\nSofort\n[q]Ein sofortiger Waffenangriff, der bis zu 4 Gegnern innerhalb von 8 Metern Heiligschaden zufügt."}
MultiLanguageSpellData['de'][165745] = {name = "Siegel der Wahrheit", additional_info = "14% von Grundmana\nSofort\n[q]Erfüllt den Paladin mit heiliger Macht, durch den Angriffe auf Einzelziele den Effekt 'Tadel' auslösen, der im Verlauf von 5 Min. [(0.01 * Zaubermacht + 0.0193 * Angriffskraft) * 5 */ 100] zusätzlichen Heiligschaden verursacht. 'Tadel' ist bis zu 0-mal stapelbar. Sobald 0 Stapel erreicht werden, verursacht jeder Angriff des Paladins zusätzlich 0% Waffenschaden als Heiligschaden. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein. Hält 5 Min. lang an.\n\n Die Entfesselung der Energie dieses Siegels fügt einem Gegner (1 + 0.223 * Zaubermacht + 0.142 * Angriffskraft) Heiligschaden zu, dieser Schaden wird für jeden Stapel von 'Tadel' auf dem Ziel um 10% erhöht."}
MultiLanguageSpellData['de'][165746] = {name = "Aura der Vergeltung", additional_info = "Sofort\n[q]Fügt jeder Kreatur, die den Zaubernden trifft, Heiligschaden zu."}
MultiLanguageSpellData['de'][165747] = {name = "Segen der Macht", additional_info = "30 Meter Reichweite\nSofort\n[q]Belegt ein verbündetes Ziel mit einem Segen, der 5 Min. lang seine Angriffskraft um 10%, seine Distanzangriffskraft um 10% erhöht und alle 5 Sek. 1% Mana regeneriert."}
MultiLanguageSpellData['de'][165748] = {name = "Demoralisierender Ruf", additional_info = "Sofort\n[q]Verringert 20 Sek. lang die Nahkampfangriffskraft von Gegnern in der Nähe."}
MultiLanguageSpellData['de'][165749] = {name = "Donnerknall", additional_info = "Sofort\n[q]Fügt nahen Gegnern Naturschaden zu, erhöht die Zeit zwischen ihren Angriffen und verringert ihre Bewegungsgeschwindigkeit. Hält 6 Sek. lang an."}
MultiLanguageSpellData['de'][165750] = {name = "Befehlsruf", additional_info = "Sofort\n[q]Erhöht die maximale Gesundheit aller Gruppenmitglieder im Umkreis von 20 Metern um 10%. Hält 2 Min. lang an."}
MultiLanguageSpellData['de'][165751] = {name = "Schockwelle", additional_info = "{Wirken in} {2 sek. 20 sek. Abklingzeit}\n[q]Schickt dem Krieger eine Energiewelle voraus, verursacht Schaden und betäubt alle Einheiten innerhalb eines kegelförmigen Bereichs von 10 Metern für 4 Sek."}
MultiLanguageSpellData['de'][165752] = {name = "Verjüngung", additional_info = "{90 Mana} {40 Meter Reichweite}\nSofort\n[q]Heilt einen Verbündeten 12 Sek. lang alle 3 Sek."}
MultiLanguageSpellData['de'][165753] = {name = "Nachwachsen", additional_info = "{280 Mana} {40 Meter Reichweite}\nWirken in 2 sek.\n[q]Heilt einen Verbündeten um einen festgelegten Wert und heilt dann 21 Sek. lang alle 3 Sek. weiteren Schaden."}
MultiLanguageSpellData['de'][165754] = {name = "Mal der Wildnis", additional_info = "30 Meter Reichweite\nSofort\n[q]Erhöht Stärke, Beweglichkeit und Intelligenz eines verbündeten Ziels 1 Stunde lang um 5%. Wenn sich das Ziel in Eurer Gruppe oder Eurem Schlachtzug befindet, werden alle Mitglieder den Effekt erhalten."}
MultiLanguageSpellData['de'][165755] = {name = "Dolchfächer", additional_info = "40 Energie\nSofort\nBenötigt Nahkampfwaffe\n[q]Wirft sofort Dolche nach allen Gegnern in der Nähe und verursacht 100% Waffenschaden."}
MultiLanguageSpellData['de'][165756] = {name = "Schmiedesturm", additional_info = "Kanalisiert (Wirken in 4 sek.)\n[q]Entfesselt einen Glutsturm, der nahen Gegnern Feuerschaden zufügt."}
MultiLanguageSpellData['de'][165757] = {name = "Feuerregen", additional_info = "{35 Mana} {30 Meter Reichweite}\nKanalisiert (Wirken in 9 sek.)\n[q]Lässt einen Feuerregen niedergehen, der alle Gegner im Zielgebiet verbrennt und ihnen 9 Sek. lang alle 3 Sek. Feuerschaden zufügt."}
MultiLanguageSpellData['de'][165758] = {name = "Feuerbrandfalle", additional_info = "{Sofort} {15 sek. Abklingzeit}\n[q]Eine Feuerfalle platzieren, die dem ersten sich nähernden Gegner im Verlauf von 15 Sek. Feuerschaden zufügt. Die Falle besteht 1 Min. lang."}
MultiLanguageSpellData['de'][165759] = {name = "Schmiedesturm", additional_info = "40 Meter Reichweite\nSofort\n[q]Entfesselt einen Glutsturm, der nahen Gegnern Feuerschaden zufügt."}
MultiLanguageSpellData['de'][165760] = {name = "Herzstoß", additional_info = "{1 Rune / -10 Runenmacht} {Nahkampfreichweite}\nSofort\nBenötigt Nahkampfwaffe\n[q]Schlägt das Ziel und seinen nächsten Verbündeten sofort. Fügt dem Primärziel 110% Waffenschaden und dem Sekundärziel 55% Waffenschaden zu."}
MultiLanguageSpellData['de'][165761] = {name = "Tod und Verfall", additional_info = "30 Meter Reichweite\nSofort\n[q]Fügt allen Zielen im Zielbereich 10 Sek. lang alle 1 Sek. Schattenschaden zu."}
MultiLanguageSpellData['de'][165762] = {name = "Horn des Winters", additional_info = "Sofort\n[q]Der Todesritter bläst das Horn des Winters und erhält 10 Runenmacht. Stärke und Beweglichkeit werden um 8 erhöht. Hält 2 Min. lang an."}
MultiLanguageSpellData['de'][165763] = {name = "Blutwurm", additional_info = "30 Meter Reichweite\nSofort\n[q]Erschafft einen Blutwurm, der nahe Ziele angreift. Hält 8 Sek. lang an."}
MultiLanguageSpellData['de'][165764] = {name = "Psychischer Schrei", additional_info = "210 Mana\nSofort\n[q]Stößt einen psychischen Schrei aus, der bis zu 5 Gegner in der Nähe für 4 Sek. in die Flucht schlägt."}
MultiLanguageSpellData['de'][165765] = {name = "Leiche auferwecken", additional_info = nil}
MultiLanguageSpellData['de'][165766] = {name = "Dispersion", additional_info = "Sofort\n[q]Löst Euch zu reiner Schattenenergie auf und verringert sämtlichen erlittenen Schaden um 75%. Ihr könnt nicht angreifen oder Zauber wirken, regeneriert jedoch 6 Sek. lang pro Sekunde 90% Mana. 'Dispersion' kann gewirkt werden, während Betäubungs-, Furcht- oder Stilleeffekte auf Euch wirken. Bei Anwendung werden alle wirkenden Verlangsamungs- und bewegungseinschränkenden Effekte entfernt und Ihr werdet für die Dauer des Effekts von 'Dispersion' gegen sie immun."}
MultiLanguageSpellData['de'][165767] = {name = "Schattengestalt", additional_info = "40% von Grundmana\nSofort\n[q]Nimmt Schattengestalt an, erhöht verursachten Schattenschaden um 20% und verringert erlittenen Nahkampfschaden um 20%. Die Schattengestalt hält an, bis die Aktion abgebrochen wird."}
MultiLanguageSpellData['de'][165768] = {name = "Schattenschritt", additional_info = "{20 Energie} {40 Meter Reichweite}\n{Sofort} {30 sek. Abklingzeit}\n[q]Versucht, in die Schatten zu tauchen, um hinter dem Gegner zu erscheinen."}
MultiLanguageSpellData['de'][165769] = {name = "Frostfalle", additional_info = "Sofort\n[q]Platziert eine Frostfalle, die 30 Sek. lang um sich herum eine Eisfläche bildet, sobald sich ihr der erste Gegner nähert. Die Bewegungsgeschwindigkeit aller Gegner in einem Umkreis von 10 Metern wird um 50% verringert, solange sie sich im Effektbereich befinden. Die Falle bleibt 30 Sek. lang bestehen. Es kann immer nur jeweils eine Falle aktiv sein."}
MultiLanguageSpellData['de'][165770] = {name = "Prankenhieb", additional_info = "Nahkampfreichweite\nSofort\n[q]Schlägt Gegner in der Nähe und verursacht körperlichen Schaden."}
MultiLanguageSpellData['de'][165771] = {name = "Dornen", additional_info = "30 Meter Reichweite\nSofort\n[q]Aus dem verbündeten Ziel sprießen Dornen, die jedem Angreifer Naturschaden zufügen. Hält 10 Min. lang an."}
MultiLanguageSpellData['de'][165772] = {name = "Welle der Heilung", additional_info = "{145 Mana} {40 Meter Reichweite}\nWirken in 3 sek.\n[q]Ruft Naturmagie an, um einen Verbündeten zu heilen."}
MultiLanguageSpellData['de'][165773] = {name = "Erdschild", additional_info = "40 Meter Reichweite\nSofort\n[q]Schützt das Ziel mit einem Erdschild. Nahkampfangriffe heilen das geschützte Ziel, dieser Effekt tritt aber nur einmal alle paar Sekunden auf. 10 Aufladungen. Hält 10 Min. lang an.\n(3.5s Abklingzeit)"}
MultiLanguageSpellData['de'][165774] = {name = "Totem der Erdbindung", additional_info = "30 Mana\nSofort\nTools: Erdtotem\n[q]Beschwört ein Totem der Erdbindung, das 45 Sek. lang bestehen bleibt und in regelmäßigen Abständen die Bewegungsgeschwindigkeit von Gegnern in der Nähe auf 50% der normalen Geschwindigkeit verringert."}
MultiLanguageSpellData['de'][165775] = {name = "Antimagisches Feld", additional_info = "1 Rune / -10 Runenmacht\nSofort\n[q]Platziert ein großes, ortsgebundenes antimagisches Feld, das den erlittenen Zauberschaden aller darin befindlichen Gruppen- oder Schlachtzugsmitglieder um 49% verringert. Das antimagische Feld hält 6 Sek. lang an oder bis es (0 + 2 * Angriffskraft) Zauberschaden absorbiert hat."}
MultiLanguageSpellData['de'][165776] = {name = "Giftdurchwobenes Netz", additional_info = "7 Meter Reichweite\nKanalisiert (Wirken in 4 sek.)\n[q]Umhüllt einen Gegner mit giftigen Netzen, die diesem alle 5.2 Sek. Naturschaden zufügen und ihn 4 Sek. lang bewegungsunfähig machen."}
MultiLanguageSpellData['de'][165777] = {name = "Giftdurchwobenes Netz", additional_info = "10 Meter Reichweite\nSofort\n[q]Umhüllt einen Gegner mit giftigen Netzen, die diesem alle 5.2 Sek. Naturschaden zufügen und ihn 4 Sek. lang bewegungsunfähig machen."}
