MultiLanguageSpellData['de'][165779] = {name = "Infizierter Biss", additional_info = "Nahkampfreichweite\nSofort\n[q]Beißt einen Gegner und verursacht eine juckende Wunde, die ihm 6 Sek. lang alle 2 Sek. Naturschaden zufügt.\n Bei Erlöschen wird ein 'Spinnlingausbruch' ausgelöst."}
