MultiLanguageSpellData['de'][171221] = {name = "Anhängerin: Beschützerin Illona", additional_info = "Sofort\n[q]Illona hatte immer davon geträumt, sich eines Tages dem uralten Auchenaiorden anzuschließen. Als Exarch Maladaar alle fähigen Draenei dazu aufrief, zu Hilfe zu eilen, griff sich Illona die Rüstung ihres Großvaters und schritt entschlossen ihrem Schicksal entgegen."}
