MultiLanguageSpellData['de'][171571] = {name = "Federgetriebene Stachelfalle", additional_info = "Sofort 1 min Abklingzeit\n[q]Platziert in der Nähe eine Dornenfalle, die darin gefangenen Gegnern (100% der Angriffskraft) körperlichen Schaden zufügt und alle Gegner innerhalb von 10 Metern verwundet, wodurch sie zusätzlich [(4.26906% der Angriffskraft) * 10] körperlichen Schaden im Verlauf von 20 Sek. erleiden. Die Falle bleibt 1 Min. lang bestehen."}
MultiLanguageSpellData['de'][171572] = {name = "Federgetriebene Stachelfalle", additional_info = "100 Meter Reichweite\nSofort\n[q]Schleudert eine Feuerfalle in den Zielbereich, die explodiert, wenn sich ein Gegner nähert. Die Falle verursacht (54.054% der Angriffskraft) Feuerschaden und fügt zusätzlich allen Gegnern innerhalb von 8 Metern im Verlauf von 10 Sek. (54.054% der Angriffskraft) Feuerschaden zu. Die Falle bleibt 1 Min. lang bestehen."}
