MultiLanguageSpellData['de'][171614] = {name = "Inferno", additional_info = "Wirken in 5 sek.\n[q]Fügt allen Gegnern im Umkreis von 45 Metern 87 Feuerschaden zu."}
MultiLanguageSpellData['de'][171615] = {name = "Herrliches Feuerwerk", additional_info = "Sofort\n[q]Entfesselt die Kraft der Liebe."}
MultiLanguageSpellData['de'][171616] = {name = "Dorrhautklippentrampler", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren Dorrhautklippentrampler oder gibt ihn wieder frei.\n[q]\"Bei dieser Grollhufart sind die Hufe mit kleinen Kerben bedeckt, was es ihr erleichtert, ungefährdet Bergregionen auf der Suche nach Nahrung zu erklimmen.\"\nVerkäufer:\nHändlerin Araanda\nZone:\nMondsturz\nKosten:\n20000\n\nVerkäufer:\nHändler Darakk\nZone:\nFrostwall\nKosten:\n20000\n\n|"}
MultiLanguageSpellData['de'][171617] = {name = "Zugerittener Eishuf", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren zugerittenen Eishuf oder gibt ihn wieder frei.\n[q]\"Bevor Euch dieses Reittier gehörte, hattet Ihr ja nicht die geringste Ahnung davon, wie schwer es in Draenor werden würde. Grollhufhaare überall!\"\nHerkunft:\nStall der Garnison"}
MultiLanguageSpellData['de'][171618] = {name = "Alte Lederhaut", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Eure alte Lederhaut oder gibt sie wieder frei."}
MultiLanguageSpellData['de'][171619] = {name = "Tundraeishuf", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren Tundraeishuf oder gibt ihn wieder frei.\n[q]\"Das durchscheinende Unterfell dieser Art ist eine perfekte Isolierung für den Einsatz in kalten Umgebungen.\"\nBeute von:\nRache, Todeskralle, Terrorfaust, Verdammniswalze\nZone:\nTanaandschungel"}
MultiLanguageSpellData['de'][171620] = {name = "Bluthufbulle", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren Bluthufbullen oder gibt ihn wieder frei.\n[q]\"Schon lange jagen die Mitglieder des Kriegshymnenklans diese Grollhufe, um ihre blutrote Haut für Schlachtstandarten zu verwenden.\"\nBeute von:\nNakk der Donnerer\nOrt:\nNagrand"}
MultiLanguageSpellData['de'][171621] = {name = "Eisenhufzerstörer", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren Eisenhufzerstörer oder gibt ihn wieder frei.\n[q]\"Es wird behauptet, dass Schwarzfaust die feurige Rüstung für die Schlachtgrollhufe der Eisernen Horde selbst entworfen hat.\"\nBeute von:\nSchwarzfaust\nOrt:\nSchwarzfelsgießerei (Mythisch)"}
MultiLanguageSpellData['de'][171622] = {name = "Scheckiger Wiesentrampler", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren scheckigen Wiesentrampler oder gibt ihn wieder frei.\n[q]\"Mit seinem langen Rüssel kann dieser Elekk Nahrung erschnüffeln, Gefahren umgehen und Leckerlis aus Eurer Tasche stibitzen, wenn Ihr gerade nicht hinseht.\"\nBeute von:\nLuk'hok\nZone:\nNagrand"}
MultiLanguageSpellData['de'][171623] = {name = "Zugerittener Wiesentrampler", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren zugerittenen Wiesentrampler oder gibt ihn wieder frei.\n[q]\"Die Draenei haben schon vor langer Zeit die Elekkhaltung perfektioniert und schmücken die Kreaturen mit lichtgetränkten Kristallen, um sie gefügig zu machen.\"\nQuest:\nStall der Garnison"}
MultiLanguageSpellData['de'][171624] = {name = "Schattenfellperlzahn", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren Schattenfellperlzahn oder gibt ihn wieder frei.\n[q]\"Einigen Legenden zufolge haben die Draenei sich mit den Elekks angefreundet, nachdem eines dieser wilden Tiere einen verletzten Späher vor einem Rudel bösartiger Schotlinge beschützt hatte.\"\nBeute von:\nZurückgelassener Invasorenschatz"}
MultiLanguageSpellData['de'][171625] = {name = "Staubige Steinhaut", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Eure staubige Steinhaut oder gibt sie wieder frei.\n[q]\"Seit Ihr dieses Reittier erworben habt, habt Ihr merkwürdige Fieberträume von einer Parade tanzender und trötender rosa Elekks. Elekks hin, Elekks her, in rosa, da stör'n sie Euch sehr!\"\nVerkäufer:\nVerteidiger Nuurem\nExarchenrat - Ehrfürchtig\nOrt:\nSturmschild\nKosten:\n5.000\n+ 5.000"}
MultiLanguageSpellData['de'][171626] = {name = "Gepanzerter Eisenzahn", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren gepanzerten Eisenzahn oder gibt ihn wieder frei.\n[q]\"Es wird behauptet, dass ein Elekk nie etwas vergisst. Es ist also kein Wunder, dass dieses Tier die Eiserne Horde verachtet, wenn man bedenkt, was für Qualen die Orcs ihm angetan haben.\"\nVerkäufer:\n\nSha'tarverteidigung - Ehrfürchtig\nOrt:\nGarnison - Handelsposten\nKosten:\n5.000\n+ 5.000"}
MultiLanguageSpellData['de'][171627] = {name = "Schwarzstahlkampfeber", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren Schwarzstahlkampfeber oder gibt ihn wieder frei.\n[q]\"Weigert sich zu rennen, wenn sein Schädel nicht mit schweren Metallstacheln bedeckt ist. Das stärkt sein Ego.\"\nErfolg:\nRuhm des Draenorschlachtzüglers"}
MultiLanguageSpellData['de'][171628] = {name = "Felshauerkampfeber", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren Schwarzstahlkampfeber oder gibt ihn wieder frei.\n[q]\"Angelockt werden potenzielle Partner nicht etwa durch den Metallhelm, sondern durch den fetzigen Irokesenschnitt.\"\nVerkäufer:\nHändlerin Araanda\nZone:\nMondsturz\nKosten:\n10000\n\nVerkäufer:\nHändler Darakk\nZone:\nFrostwall\nKosten:\n10000\n\n|"}
MultiLanguageSpellData['de'][171629] = {name = "Gepanzerter Frosteber", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren gepanzerten Frosteber oder gibt ihn wieder frei.\n[q]\"Ernährt sich praktisch ausschließlich von gefrorenen Beeren. Gibt sich jedoch auch mit dem Geschmack von langsamen Fremdlingen zufrieden.\"\nErfolg:\nFortgeschrittene Viehhaltung"}
MultiLanguageSpellData['de'][171630] = {name = "Gepanzerter Klingenrücken", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren gepanzerten Klingenrücken oder gibt ihn wieder frei.\n[q]\"Passt bloß auf, dass er... NIEMALS... Schinken in Eurer Tasche riecht.\"\nBeute von:\nRache, Todeskralle, Terrorfaust, Verdammniswalze\nZone:\nTanaandschungel"}
MultiLanguageSpellData['de'][171631] = {name = "Achievement Credit", additional_info = "Sofort\n[q]Gestattet es Euch, in Eurer Garnison Gildenbanner aufzustellen."}
MultiLanguageSpellData['de'][171632] = {name = "Frostebenenkampfeber", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren Frostebenenkampfeber oder gibt ihn wieder frei.\n[q]\"Ohne dieses coole Hauerpiercing würde er sich in dem Outfit echt bekloppt vorkommen.\"\nErfolg:\nRuhm des Draenorhelden"}
MultiLanguageSpellData['de'][171633] = {name = "Wilder Geiferzahn", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren wilden Geiferzahn oder gibt ihn wieder frei.\n[q]\"Wenn Ihr gemütlich reiten möchtet, sucht Euch doch einen \"zahmen Glückshauer\" oder so.\"\nVerkäufer:\nZ'tenga der Wanderer\nZone:\nTanaandschungel\nDie Säbelzahnpirscher - Wohlwollend\nKosten:\n1.000"}
MultiLanguageSpellData['de'][171634] = {name = "Domestizierter Klingenrücken", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren domestizierten Klingenrücken oder gibt ihn wieder frei.\n[q]\"Domestiziert\" heißt nicht \"freundlich\". Bringt also Leckerlis mit.\nVerkäufer:\nGazrix Kolbenfresser/Mimi Wirbelwolke\nWerterhaltungsgesellschaft des Dampfdruckkartells - Ehrfürchtig\nOrt:\nSturmschild/Kriegsspeer\nKosten:\n5.000\n+ 5.000"}
MultiLanguageSpellData['de'][171635] = {name = "Riesige Kaltschnauze", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Eure riesige Kaltschnauze oder gibt sie wieder frei.\n[q]\"Die Schnauze ist nicht nur kalt, sondern auch nass. Es gibt angenehmere Methoden, aufgeweckt zu werden.\"\nBeute von:\nZurückgelassener Invasorenschatz"}
MultiLanguageSpellData['de'][171636] = {name = "Mächtiger Grauhauer", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren mächtigen Grauhauer oder gibt ihn wieder frei.\n[q]\"Wirft seine Hauer einmal im Jahr ab und ist äußert schüchtern, bis sie nachgewachsen sind.\"\nBeute von:\nGorok\nZone:\nFrostfeuergrat"}
MultiLanguageSpellData['de'][171637] = {name = "Zugerittener Felshauer", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren zugerittenen Felshauer oder gibt ihn wieder frei.\n[q]\"Gründlich darin ausgebildet, wie man schnaubt, trötet und auf den Gesichtern seiner Feinde herumtrampelt.\"\nQuest:\nStall der Garnison"}
MultiLanguageSpellData['de'][171638] = {name = "Zugerittener Flussfläzer", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren zugerittenen Flussfläzer oder gibt ihn wieder frei.\n[q]\"Flussfläzer gehören zu den kräftigsten Tieren in Draenor, was ihnen mehr Ausdauer und eine markante Färbung verleiht.\"\nQuest:\nStall der Garnison"}
