MultiLanguageSpellData['de'][171824] = {name = "Saphirblaue Flussbestie", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Eure saphirblaue Flussbestie oder gibt sie wieder frei.\n[q]\"Die Farbe des Tiers ähnelt dem klaren Blau der Flüsse Draenors und macht es für Raubtiere im Wasser nahezu unsichtbar.\"\nBeute von:\nSchlickhaut\nZone:\nTalador"}
MultiLanguageSpellData['de'][171825] = {name = "Mooshautflussfläzer", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren Mooshautflussfläzer oder gibt ihn wieder frei.\n[q]\"Die Mooshaut verteidigt ihr Gebiet aggressiv und versteckt sich häufig im Buschwerk an Flüssen, um ahnungslose Passanten zu attackieren.\"\nVerkäufer:\nDämmerungssucher Krek / Dämmerungssucher Alkset\nOrt:\nSturmschild/Kriegsspeer\nKosten:\n50.000\n+ 5.000"}
MultiLanguageSpellData['de'][171826] = {name = "Schlammrückenflussbestie", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Eure Schlammrückenflussbestie oder gibt sie wieder frei.\n[q]\"Ein spezielles Gewebe an den Fußsohlen des Schlammrückens gewährt ihm zusätzlichen Halt in Schlamm und auf rutschigen Untergründen.\"\nGarnisonsmission:\nIst es ein Schiff? Ist es ein Flugzeug? Nein, nur eine Flussbestie!"}
MultiLanguageSpellData['de'][171827] = {name = "Höllenfeuerbestie", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Eure Höllenfeuerbestie oder gibt sie wieder frei.\n[q]\"Aus den Tiefen des Nethers wird eine Kreatur heraufbeschworen, die aus purem Hass besteht und danach trachtet, alles Leben auf ihrem Wege auszulöschen.\"\nBeute von:\nGul'dan (Mythisch)\nZone:\nDie Nachtfestung"}
MultiLanguageSpellData['de'][171828] = {name = "Sonnenfalke der Spitzen", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren Sonnenfalken der Spitzen oder gibt ihn wieder frei.\n[q]\"Wenn man in die Augen dieses mystischen Wesens blickt, hat man das Gefühl, man würde in das Herz der Sonne starren. Beim Reiten ist das Tragen einer Schutzbrille anzuraten.\"\nBeute von:\nRukhmar"}
MultiLanguageSpellData['de'][171829] = {name = "Schattenmähnenstürmer", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren Schattenmähnenstürmer oder gibt ihn wieder frei.\n[q]\"Draeneidichter bezeichnen die Farbe dieses Talbuks als Schatten des Mondlichts im aschgrauen Wald.\"\nVerkäufer:\nRabensprecher Skeega / Schattenweiser Brakoss\nAusgestoßene Arakkoa - Ehrfürchtig\nOrt:\nSturmschild/Kriegsspeer\nKosten:\n5.000\n+ 5.000"}
MultiLanguageSpellData['de'][171830] = {name = "Flinker Brisenschreiter", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren flinken Brisenschreiter oder gibt ihn wieder frei.\n[q]\"Die Draenei haben dieses Reittier, das schnellste aller Talbuks, mit der Aufgabe betraut, ihre Boten und Nachrichten sicher an ihre Ziele zu bringen.\"\nBeute von:\nPfadläufer\nZone:\nSchattenmondtal"}
MultiLanguageSpellData['de'][171831] = {name = "Zugerittenes Silberfell", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euer zugerittenes Silberfell oder gibt es wieder frei.\n[q]\"Dieser Talbuk ist aufgrund seiner Intelligenz beliebt und wird darauf trainiert, im Kampf zu treten und Gegner aufzuspießen.\"\nOrt:\nStall der Garnison"}
MultiLanguageSpellData['de'][171832] = {name = "Brisenschreiterhengst", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren Brisenschreiterhengst oder gibt ihn wieder frei.\n[q]\"Die rote Färbung des Brisenschreiters spiegelt sein Temperament wider: lebhaft, stürmisch und tapfer.\"\nVerkäufer:\nDazzerian\nVol'jins Speer - Ehrfürchtig\nOrt:\nKriegsspeer\nKosten:\n5.000\n+ 5.000"}
MultiLanguageSpellData['de'][171833] = {name = "Heller Dornzehrer", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren hellen Dornzehrer oder gibt ihn wieder frei.\n[q]\"Dieser Talbuk ernährt sich ausschließlich von Disteln und Dornen, weshalb sein Inneres genauso widerstandsfähig ist, wie sein Äußeres.\"\nVerkäufer:\nMagor Geistbeuger\nWrynns Vorhut - Ehrfürchtig\nOrt:\nSturmschild\nKosten:\n5.000\n+ 5.000"}
MultiLanguageSpellData['de'][171834] = {name = "Boshafter Kriegswidder", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren boshaften Kriegswidder oder gibt ihn wieder frei.\n[q]\"Bevor er Eure empfindlichsten Körperregionen nicht mit seinem Kopf rammt, hat er Euch nicht wirklich als seinen Reiter akzeptiert.\"\nVerkäufer:\nNekrolord Sipe\nZone:\nSturmwind\nKosten:\n1"}
MultiLanguageSpellData['de'][171835] = {name = "Boshafter Kriegsraptor", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren boshaften Kriegsraptor oder gibt ihn wieder frei.\n[q]\"Weil scharfe Zähne und Klauen einfach nicht ausreichen.\"\nVerkäufer:\nTodeswache Netharian\nZone:\nOrgrimmar\nKosten:\n1"}
MultiLanguageSpellData['de'][171836] = {name = "Stahlzahngarn", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren Stahlzahngarn oder gibt ihn wieder frei.\n[q]\"Ein Trainer versuchte einst, das Maul des Stahlrachenwolfs mit Metalldekorationen zu verschönern. Drei Tage hat es gedauert, bis er sein Material zurückhatte.\"\nBeute von:\nZurückgelassener Invasorenschatz"}
MultiLanguageSpellData['de'][171837] = {name = "Terrorzahn des Kriegshymnenklans", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren Terrorzahn des Kriegshymnenklans oder gibt ihn wieder frei.\n[q]\"Dieses Tier hat einen eisernen Willen, doch wenn Ihr ihm einen Grollhufknochen zum Zerkauen bringt, ist es ganz lieb.\"\nBeute von:\nRache, Todeskralle, Terrorfaust, Verdammniswalze\nZone:\nTanaandschungel"}
MultiLanguageSpellData['de'][171838] = {name = "Gepanzerter Frostwolf", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren gepanzerten Frostwolf oder gibt ihn wieder frei.\n[q]\"Er ist dazu ausgebildet, das harsche Wetter des Frostfeuergrats zu überleben, also kuschelt er, als würde sein Leben davon abhängen.\"\nErfolg:\nStallmeister"}
MultiLanguageSpellData['de'][171839] = {name = "Eisenflankenkriegswolf", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren Eisenflankenkriegswolf oder gibt ihn wieder frei.\n[q]\"An seinem Schwanz hängt ein gepanzerter Stachel. Wenn Ihr seinen Bauch unbedingt kraulen wollt, tut Ihr es auf eigene Gefahr.\"\nVerkäufer:\nHau'tot\nLachender Schädel - Ehrfürchtig\nOrt:\nGarnison - Handelsposten (Horde)\nKosten:\n5.000\n+ 5.000"}
MultiLanguageSpellData['de'][171840] = {name = "Kaltflammenhöllenbestie", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Eure Kaltflammenhöllenbestie oder gibt sie wieder frei.\n[q]\"Die eigenartigen, eisigen Flammen lassen Euch gleichzeitig schwitzen und frieren.\"\nHandelsposten"}
MultiLanguageSpellData['de'][171841] = {name = "Zugerittener Knurrer", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren zugerittenen Knurrer oder gibt ihn wieder frei.\n[q]\"Als Welpe unheimlich süß. Jetzt nicht mehr so sehr.\"\nQuest:\nStall der Garnison"}
MultiLanguageSpellData['de'][171842] = {name = "Schneller Frostwolf", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren schnellen Frostwolf oder gibt ihn wieder frei.\n[q]\"In den kalten Höhen des Frostfeuergrats jagen die Frostwölfe allem nach, was sie fangen können. Die Schnellsten von ihnen bekommen reichlich zu beißen.\"\nVerkäufer:\nBeska Rothauer\nFrostwolforcs - Ehrfürchtig\nOrt:\nKriegsspeer\nKosten:\n5.000\n+ 5.000"}
MultiLanguageSpellData['de'][171843] = {name = "Rauchgrauer Terrorwolf", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren rauchgrauen Terrorwolf oder gibt ihn wieder frei.\n[q]\"Man vermutet, dass sie größtenteils im Norden hausen. Können Hochzeiten absolut nicht leiden.\"\nBeute von:\nZurückgelassener Invasorenschatz"}
MultiLanguageSpellData['de'][171844] = {name = "Staubmähnenterrorwolf", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren Staubmähnenterrorwolf oder gibt ihn wieder frei.\n[q]\"Staubmähnen sind verglichen mit anderen Terrorwölfen eher zurückhaltend. Damit sie sich als Reittiere verdingen, müssen Sie mit etwas überzeugt werden, das für sie etwas Besonderes darstellt.\"\nBeruf:\nLederverarbeitung"}
MultiLanguageSpellData['de'][171845] = {name = "Todesrad des Kriegsherrn", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euer Todesrad des Kriegsherrn oder gibt es wieder frei.\n[q]\"Dieses brüllende Ungetüm wird häufig als \"Goblinrasenmäher\" bezeichnet, da dieses knurrende Monstrum Feinde behandelt, als wären sie aus Gras... das bereit ist, gemäht zu werden.\"\nErfolg:\nKategorie:\nHeldentaten"}
MultiLanguageSpellData['de'][171846] = {name = "Kettenrad des Champions", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euer Kettenrad des Champions oder gibt es wieder frei.\n[q]\"Menschen, Gnome und Zwerge haben gemeinsam dieses gepanzerte Meisterstück geschaffen, das einen Tauren im Handumdrehen in mundgerechte Stücke zerteilt.\"\nVerkäufer:\nPaulie\nZone:\nSturmwind, Altstadt\nKosten:\n100000"}
MultiLanguageSpellData['de'][171847] = {name = "Glutmähnenschlachtross", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euer Glutmähnenschlachtross oder gibt es wieder frei.\n[q]\"Von Ragnaros persönlich als Geschenk für die Tochter erschaffen, die er nie hatte.\"\nWerbt einen Freund"}
MultiLanguageSpellData['de'][171848] = {name = "Kriegsyeti des Herausforderers", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren Kriegsyeti des Herausforderers oder gibt ihn wieder frei.\n[q]\"Glücklicherweise bewegen sie sich schnell und hinterlassen nur den Geruch.\"\nErfolg:\nHerausforderungskriegsherr: Silber"}
MultiLanguageSpellData['de'][171849] = {name = "Sonnenhautgronnling", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren Sonnenhautgronnling oder gibt ihn wieder frei.\n[q]\"Liebt die Sonne und hasst alles andere.\"\nBeute von:\nRammfaust\nZone:\nGorgrond"}
MultiLanguageSpellData['de'][171850] = {name = "Llothienstreuner", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren Llothienstreuner oder gibt ihn wieder frei.\n[q]\"Diese geschmeidigen Füchse können trotz ihrer Größe geräuschlos über frisch gefallene Blätter streifen.\"\nQuest:\nDer scheue Volpin\nZone:\nSuramar"}
MultiLanguageSpellData['de'][171851] = {name = "Nachtheuler der Garn", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren Nachtheuler der Garn oder gibt ihn wieder frei.\n[q]\"Die Garn gehören zu den gefährlichsten Raubtieren in Draenor und jagen immer im Rudel.\"\nBeute von:\nNok-Karosh\nOrt:\nFrostfeuergrat"}
