MultiLanguageSpellData['de'][172538] = {name = "Zertrümmernde Klinge", additional_info = "Unbegrenzte Reichweite\nWirken in 1.5 sek.\n[q]Gar schrammt mit seiner Klinge über den Boden und verursacht Funken, die Gegnern innerhalb des Effektbereichs 6 Feuerschaden zufügen."}
MultiLanguageSpellData['de'][172539] = {name = "Antiseptischer Verband", additional_info = "Wirken in 2 sek.\nReagenzien:\nPrächtiges Fell (5)\n[q]Rezept für 4 Einheiten. Die tatsächliche Anzahl hängt von Eurer Erste-Hilfe-Fertigkeit ab.\nBeruf:\nSchneiderei von Draenor (1)\n\n[q2]Benutzen: Heilt im Verlauf von 8 Sek. 2720 Schaden.\n35\n[q]\"Die heilenden Eigenschaften des Seeskorpiongiftes können über die Haut aufgenommen werden, aber sie wirken nur langsam.\""}
MultiLanguageSpellData['de'][172540] = {name = "Heiltonikum", additional_info = "Wirken in 2 sek.\nReagenzien:\nSeeskorpionsegment (10)\n[q]Erschafft 4 Stück Heiltonikum. Die tatsächliche Anzahl kann basierend auf der Fertigkeitsstufe variieren.\nBeruf:\nAlchemie von Draenor (1)\n\n[q2]Benutzen: Stellt 3400 Gesundheit wieder her. (5 Min Abklingzeit)\n35\n[q]\"Richtig vorbereitet kann das Gift des Seeskorpions Gesundheit wiederherstellen.\""}
MultiLanguageSpellData['de'][172541] = {name = "Schwarzwassergegengift", additional_info = "Wirken in 2 sek.\nReagenzien:\nFleisch einer Schwarzwasserpeitschflosse (10)\n[q]Erschafft 4 Stück Schwarzwassergegengift. Die tatsächliche Anzahl kann basierend auf der Fertigkeitsstufe variieren.\nBeruf:\nAlchemie von Draenor (1)\n\n\n35"}
