MultiLanguageSpellData['de'][178534] = {name = "Hexenmeisterportale", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Die Hexenmeister des Vorpostens des Kriegsspeers haben die Portale in Ashran aktiviert.\n\n Auf Eurer Karte findet Ihr sie im Nordwesten und Südosten Ashrans. Benutzt sie, um schneller durch Ashran zu reisen.\n\n Wenn 400 [Artefaktfragmente] , die in ganz Ashran gefunden werden können, bei Nisstyr im Vorposten des Kriegsspeers abgegeben wurden, werden die Portale aktiviert."}
MultiLanguageSpellData['de'][178535] = {name = "Hexenmeisterportale", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Die Hexenmeister der Sturmschildfeste haben die Portale in Ashran aktiviert.\n\n Auf Eurer Karte findet Ihr sie im Nordwesten und Südosten Ashrans. Benutzt sie, um schneller durch Ashran zu reisen.\n\n Wenn 400 [Artefaktfragmente] , die in ganz Ashran gefunden werden können, bei Marketa im Vorposten des Kriegsspeers abgegeben wurden, werden die Portale aktiviert."}
MultiLanguageSpellData['de'][178536] = {name = "Wolfsreiter", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Die Wolfsreiter des Vorpostens des Kriegsspeers sind ausgesandt worden, um in den Außenbereichen von Ashran alle Allianzmitglieder aufzuspüren, die sich dort aufhalten.\n\n Zum Ausrüsten der Wolfsreiter werden [Artefaktfragmente] benötigt, die in ganz Ashran zu finden sind. Gebt sie bei Kalgan im Vorposten des Kriegsspeers ab."}
MultiLanguageSpellData['de'][178537] = {name = "Kavallerie der Vergeltung", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Die Sturmschildkavallerie ist ausgesandt worden, um in den Außenbereichen von Ashran alle Mitglieder der Horde aufzuspüren, die sich dort aufhalten.\n\n Zum Ausrüsten der Kavallerie werden [Artefaktfragmente] benötigt, die in ganz Ashran zu finden sind. Gebt sie bei Valant Lichtschwur in der Sturmschildfeste ab."}
MultiLanguageSpellData['de'][178538] = {name = "Magierportal", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Die Magier der Sturmschildfeste haben das Magierportal in Ashran aktiviert. Benutzt das Portal, um schnell zur Sturmschildfeste zurückzukehren.\n\n Auf Eurer Karte findet Ihr das Magierportal westlich der Ruhestätte der Könige.\n\n Wenn 400 [Artefaktfragmente] , die in ganz Ashran gefunden werden können, bei Ecilam in der Sturmschildfeste abgegeben wurden, wird das Portal aktiviert."}
MultiLanguageSpellData['de'][178539] = {name = "Magierportal", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Die Magier des Vorpostens des Kriegsspeers haben das Magierportal in Ashran aktiviert. Benutzt das Portal, um schnell zum Vorposten des Kriegsspeers zurückzukehren.\n\n Auf Eurer Karte findet Ihr das Magierportal westlich der Ruhestätte der Könige.\n\n Wenn 400 [Artefaktfragmente] , die in ganz Ashran gefunden werden können, bei Fura im Vorposten des Kriegsspeers abgegeben wurden, wird das Portal aktiviert."}
