MultiLanguageSpellData['de'][181299] = {name = "Packende Hände", additional_info = "Wirken in 2 sek.\n[q]Kormrok beschwört mehrere Steinhände unter den Füßen seiner Gegner, die allen Gegnern in einem Umkreis von 4 Metern um das Opfer 2301 körperlichen Schaden zufügen. Die Hände halten das Opfer fest, bis es vernichtet ist.\n\n Während es gepackt ist, erleidet das Opfer alle 3 Sek. 3098 körperlichen Schaden."}
MultiLanguageSpellData['de'][181300] = {name = "Verschleppende Hände", additional_info = "Wirken in 2 sek.\n[q]Kormrok beschwört mehrere Steinhände unter den Füßen seiner Gegner. Diese Hände zerren ihre Opfer zur nächsten Pfütze mit Teufelsenergie.\n\n Während sie gepackt sind, erleiden Opfer alle 3 Sek. 35 körperlichen Schaden."}
