MultiLanguageSpellData['de'][184818] = {name = "Anhängerin: Lady Liadrin", additional_info = "Sofort\n[q]Lady Liadrin wurde schon vieles genannt - übereifrig, arrogant, aufbrausend -, aber die Matriarchin der Blutritter hat sich nie an diesen Hänseleien gestört. Nenne man sie, wie man will, aber in Liadrins Augen gibt es nur eins, das zählt: die absolute Vernichtung der Brennenden Legion."}
MultiLanguageSpellData['de'][184819] = {name = "Anhängerin: Aponi Lichtmähne", additional_info = "Sofort\n[q]Aponi Lichtmähne, Anführerin der aufsteigenden Sonnenläuferpaladine, einte ihr nach Wahrheit und Wissen dürstendes Volk. Was ist die wahre Natur des Lichts? Warum gewährt es uns seine Stärke? Aponi ist fest entschlossen, Antworten auf diese brennenden Fragen zu finden, und hat keine Hemmungen, alles und jeden, der ihr dabei im Weg steht, zu beseitigen."}
