MultiLanguageSpellData['de'][187617] = {name = "Sanctus", additional_info = "100 Meter Reichweite\nSofort\n[q]Erweckt die Mächte der Ringe von Sanctus, die von Euch und Euren Verbündeten getragen werden, um 15 Sek. lang [(( 80 > 109 ? 0.01 : ( 80 < 100 ? 1 : (110 - 80) / 10))) * 450 / 100]% Vielseitigkeit zu gewähren.\n\n Für die Dauer dieses Effekts werden sämtlicher erlittener Schaden und alle erhaltene Heilung gleichmäßig unter den ermächtigten Verbündeten aufgeteilt. (2 Min. geteilte Abklingzeit)"}
MultiLanguageSpellData['de'][187618] = {name = "Etheralus", additional_info = "100 Meter Reichweite\nSofort\n[q]Erweckt die Mächte der Ringe von Etheralus, die von Euch und Euren Verbündeten getragen werden, um die hervorgerufene Heilung und Absorption 15 Sek. lang um [(( 80 > 109 ? 0.01 : ( 80 < 100 ? 1 : (110 - 80) / 10))) * 225 / 100]% zu erhöhen.\n\n Wenn dieser Effekt endet, entfesselt jeder ermächtigte Spielercharakter einen Energieausbruch, der Verbündete abschirmt und Schaden in Höhe von ( 225 / 100)% der gesamten Heilung absorbiert, die der Spielercharakter während der Ermächtigung hervorgerufen hat. Der Effekt wird gleichmäßig auf alle abgeschirmten Spielercharaktere verteilt. (2 Min. geteilte Abklingzeit)"}
MultiLanguageSpellData['de'][187619] = {name = "Thorasus", additional_info = "300 Meter Reichweite\nSofort\n[q]Erweckt die Mächte aller wilden Heiligtümer, die von Euch und Euren Verbündeten getragen werden, und erhöht den verursachten Schaden 15 Sek. lang um [(( 80 > 109 ? 0.01 : ( 80 < 100 ? 1 : (110 - 80) / 10))) * 225 / 100]%.\n\n Wenn dieser Effekt endet, entfesselt jeder von Macht erfüllte Spielercharakter einen Blitz aus Licht, der alle Gegner innerhalb von 20 Metern vom auslösenden Spielercharakter trifft und ihnen Schaden in Höhe von ( 225 / 100)% des gesamten Schadens, den er unter der Ermächtigung verursacht hat, zufügt. (2 Min. geteilte Abklingzeit)"}
