MultiLanguageSpellData['de'][187878] = {name = "Tobende Blitze", additional_info = "Sofort\n[q]Versetzt allen Gegnern vor Euch einen Stromschlag, der [(91.08% der Angriffskraft) * [(Angriffskraft * 0.98)][((Angriffskraft + Schildhand-Angriffskraft) * 2 / 3)] -- 2H, DW / Angriffskraft] Naturschaden verursacht. Wenn mindestens 2 Ziele getroffen werden, werden Eure Waffen 12 Sek. lang verstärkt, wodurch 'Sturmschlag', 'Eisstoß' und 'Lavapeitsche' allen Zielen vor Euch zusätzlich [(27.6% der Angriffskraft) * [(Angriffskraft * 0.98)][((Angriffskraft + Schildhand-Angriffskraft) * 2 / 3)] -- 2H, DW / Angriffskraft] Naturschaden zufügen. Fügt Zielen über 6 Ziele hinaus verringerten Schaden zu. [ Zusammenströmende Stürme : Jedes von 'Tobende Blitze' getroffene Ziel erhöht den verursachten Schaden Eures nächsten Einsatzes von 'Sturmschlag' um 25%, bis maximal 6 Stapel ]"}
MultiLanguageSpellData['de'][187879] = {name = "Leerenblick", additional_info = "40 Meter Reichweite\nWirken in 1 sek.\n[q]Fügt einem zufälligen Ziel 8061 Schattenschaden zu, springt auf zusätzliche Ziele innerhalb von 5 Metern über und verursacht mit jedem Sprung mehr Schaden."}
MultiLanguageSpellData['de'][187880] = {name = "Waffe des Mahlstroms", additional_info = "[q]Wenn Ihr mit einer Nahkampfwaffe Schaden verursacht, besteht eine Chance, dass Ihr 'Waffe des Mahlstroms' erhaltet, was bis zu 5-mal stapelbar ist. Jeder Stapel von 'Waffe des Mahlstroms' verringert die Zauberzeit Eures nächsten Schadens- oder Heilzaubers um 20% [ Verbesserte Waffe des Mahlstroms : und erhöht dessen Schaden um 0% oder dessen Heilung um 0% ].\n\n Es können maximal 5 Stapel von 'Waffe des Mahlstroms' auf einmal aufgebraucht werden.\n(Procchance: 20%)"}
