MultiLanguageSpellData['de'][189775] = {name = "Mächtige Dämonenketten", additional_info = "Unbegrenzte Reichweite\nWirken in 3 sek.\n[q]Sobald Akkelion besiegt ist, absorbiert Xhul'horac seine Macht und erhält 'Mächtige Dämonenketten'.\n\n Verbindet Spielercharaktere mit Teufelsketten, die pro Sekunde pro Stapel 1193 Feuerschaden verursachen. Spielercharaktere erhalten einen Stapel für jeden Spielercharakter, mit dem sie verbunden sind.\n\n Betroffene Spielercharakter können sich von den mit ihnen verbundenen Spielercharakteren entfernen, um die Ketten zu brechen. Das Brechen von 'Mächtige Dämonenketten' löst 'Dämonischer Rückschlag' aus."}
MultiLanguageSpellData['de'][189776] = {name = "Mächtige Dämonenketten", additional_info = "Sofort\n[q]Verbindet Spielercharaktere mit Teufelsketten, die pro Sekunde pro Stapel 1193 Feuerschaden verursachen. Spielercharaktere erhalten einen Stapel für jeden Spielercharakter, mit dem sie verbunden sind.\n\n Betroffene Spielercharakter können sich von den mit ihnen verbundenen Spielercharakteren entfernen, um die Ketten zu brechen."}
MultiLanguageSpellData['de'][189777] = {name = "Mächtige Dämonenketten", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Verbindet Spielercharaktere mit Teufelsketten, die pro Sekunde pro Stapel 1193 Feuerschaden verursachen. Spielercharaktere erhalten einen Stapel für jeden Spielercharakter, mit dem sie verbunden sind.\n\n Betroffene Spielercharakter können sich von den mit ihnen verbundenen Spielercharakteren entfernen, um die Ketten zu brechen."}
MultiLanguageSpellData['de'][189778] = {name = "Mächtige Dämonenketten", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Verbindet Spielercharaktere mit Teufelsketten, die pro Sekunde pro Stapel 1193 Feuerschaden verursachen. Spielercharaktere erhalten einen Stapel für jeden Spielercharakter, mit dem sie verbunden sind.\n\n Betroffene Spielercharakter können sich von den mit ihnen verbundenen Spielercharakteren entfernen, um die Ketten zu brechen."}
MultiLanguageSpellData['de'][189779] = {name = "Mächtiges schwarzes Loch", additional_info = "Unbegrenzte Reichweite\nWirken in 3 sek.\n[q]Sobald Omnus besiegt ist, absorbiert Xhul'horac seine Macht und erhält 'Mächtiges schwarzes Loch'.\n\n Reißt ein Loch in das Gewebe der Realität, fügt allen Spielercharakteren alle 1 Sek. 1136 körperlichen Schaden zu und zieht sie zum schwarzen Loch. Wenn ein Spielercharakter ins schwarze Loch gerät, löst er 'Singularität' aus."}
