MultiLanguageSpellData['de'][194775] = {name = "Brennender Reifen", additional_info = "Wirken in 3.5 sek.\nReagenzien:\nSteinbalgleder (50), Teufelsbalg (5)\n[q]Stellt einen brennenden Reifen her.\nVerkäufer:\nLaura Malley\nZone:\nKanalisation von Dalaran\nKosten:\n100\n\nEinzigartig\nSpielzeug\n[q2]Benutzen: Hält einen brennenden Reifen hoch, damit Euer Haustier hindurchspringt! (6 Sek. Abklingzeit)\n1 - 80 ( 80)"}
