MultiLanguageSpellData['de'][195932] = {name = "[q4]Magischer Schattenrubinanhänger", additional_info = "Wirken in 2.5 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nSchattenrubin (4), Wutstein , Pandemonit , Infernoschwefel (2), Blut von Sargeras (5)\nOptionale Reagenzien:\n[] (#49)\n[q]Verringert erheblich die erforderlichen Materialien zur Herstellung eines magischen Schattenrubinanhängers.\nBeute von:\nCalamir\nZone:\nAzsuna\n\n[q4]Magischer Schattenrubinanhänger\nWird beim Anlegen gebunden\nHals\n+4 Ausdauer\n\n[q0]Prismatischer Sockel\n\nKlassen: Magier\n[q2]Benutzen: Wirkt einen zufälligen Schadenszauber auf Euer Ziel. (5 Min Abklingzeit)\n45"}
MultiLanguageSpellData['de'][195933] = {name = "[q3]Gesegnetes Morgenlichtmedaillon", additional_info = "Wirken in 2.5 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nMorgenlicht (4), Wutstein , Pandemonit , Infernoschwefel (2), Blut von Sargeras (5)\nOptionale Reagenzien:\n[] (#49)\n[q]Verringert erheblich die erforderlichen Materialien zur Herstellung eines gesegneten Morgenlichtmedaillons.\nBeute von:\nHelya\nZone:\nDer Seelenschlund (Heroisch)\n\n[q3]Gesegnetes Morgenlichtmedaillon\nWird beim Anlegen gebunden\nHals\n+4 Ausdauer\n\n[q0]Prismatischer Sockel\n\nKlassen: Priester\n[q2]Benutzen: Heilt Euch um 89 Gesundheit und stellt 19 Mana wieder her. (5 Min Abklingzeit)\n45"}
MultiLanguageSpellData['de'][195934] = {name = "[q4]Verschlungener Pandemonithalsreif", additional_info = "Wirken in 2.5 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nPandemonit (3), Wutstein , Infernoschwefel (2), Blut von Sargeras (5)\nOptionale Reagenzien:\n[] (#49)\n[q]Verringert erheblich die erforderlichen Materialien zur Herstellung eines verschlungenen Pandemonithalsreifs.\nVerkäufer:\nMarin Klingenflügel\nZone:\nAzsuna\nDie Wächterinnen - Ehrfürchtig\nKosten:\n3000\n\n[q4]Verschlungener Pandemonithalsreif\nWird beim Anlegen gebunden\nHals\n+4 Ausdauer\n\n[q0]Prismatischer Sockel\n\nKlassen: Hexenmeister\n[q2]Anlegen: Heilt Euch um 355 Gesundheit, wenn Euer beschworener Dämon stirbt. Kann nur ein Mal alle 3 Min. auftreten.\n45"}
MultiLanguageSpellData['de'][195935] = {name = "[q4]Verstohlener Schattenrubinanhänger", additional_info = "Wirken in 2.5 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nSchattenrubin (4), Wutstein , Pandemonit , Infernoschwefel (2), Blut von Sargeras (5)\nOptionale Reagenzien:\n[] (#49)\n[q]Verringert erheblich die erforderlichen Materialien zur Herstellung eines verstohlenen Schattenrubinanhängers.\nVerkäufer:\nErste Arkanistin Thalyssra\nZone:\nSuramar\nDie Nachtsüchtigen - Ehrfürchtig\nKosten:\n3000\n\n[q4]Verstohlener Schattenrubinanhänger\nWird beim Anlegen gebunden\nHals\n+4 Ausdauer\n\n[q0]Prismatischer Sockel\n\nKlassen: Schurke\n[q2]Anlegen: Wenn Ihr einem Gegner einen Todesstoß versetzt, der Erfahrung oder Ehre gewährt, wird die verbleibende Abklingzeit von 'Sprinten' um 10 Sek. verringert.\n45"}
MultiLanguageSpellData['de'][195936] = {name = "[q4]Stille Prophezeiungshalskette", additional_info = "Wirken in 2.5 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nAuge der Prophezeiung (4), Wutstein , Pandemonit , Infernoschwefel (2), Blut von Sargeras (5)\nOptionale Reagenzien:\n[] (#49)\n[q]Verringert erheblich die erforderlichen Materialien zur Herstellung einer stillen Prophezeiungshalskette.\nBeute von:\nBerater Vandros\nZone:\nDer Arkus (Heroisch)\n\n[q4]Stille Prophezeiungshalskette\nWird beim Anlegen gebunden\nHals\n+4 Ausdauer\n\n[q0]Prismatischer Sockel\n\nKlassen: Mönch\n[q2]Anlegen: 'Rollen', 'Chitorpedo' oder Springen heilt Euch um 44 Gesundheit. Dieser Effekt kann nur ein Mal alle 20 Sek. auftreten. (20s Abklingzeit)\n45"}
MultiLanguageSpellData['de'][195937] = {name = "[q4]Rachsüchtiger Pandemonithalsreif", additional_info = "Wirken in 2.5 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nPandemonit (3), Wutstein , Infernoschwefel (2), Blut von Sargeras (5)\nOptionale Reagenzien:\n[] (#49)\n[q]Verringert erheblich die erforderlichen Materialien zur Herstellung eines rachsüchtigen Pandemonithalsreifs.\nBeute von:\nCordana Teufelsang\nZone:\nDas Verlies der Wächterinnen (Heroisch)\n\n[q4]Rachsüchtiger Pandemonithalsreif\nWird beim Anlegen gebunden\nHals\n+4 Ausdauer\n\n[q0]Prismatischer Sockel\n\nKlassen: Dämonenjäger\n[q2]Benutzen: Reflektiert für 20 Sek. 18 Chaosschaden auf Angreifer. (1s Abklingzeit) (5 Min Abklingzeit)\n45"}
MultiLanguageSpellData['de'][195938] = {name = "[q4]Laubgrünes Mahlstromamulett", additional_info = "Wirken in 2.5 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nMahlstromsaphir (4), Wutstein , Pandemonit , Infernoschwefel (2), Blut von Sargeras (5)\nOptionale Reagenzien:\n[] (#49)\n[q]Verringert erheblich die erforderlichen Materialien zur Herstellung eines laubgrünen Mahlstromamuletts.\nBeute von:\nSchemen von Xavius\nZone:\nDas Finsterherzdickicht (Heroisch)\n\n[q4]Laubgrünes Mahlstromamulett\nWird beim Anlegen gebunden\nHals\n+4 Ausdauer\n\n[q0]Prismatischer Sockel\n\nKlassen: Druide\n[q2]Anlegen: Erhöht die Vielseitigkeit im Freien um 10 .\n45"}
MultiLanguageSpellData['de'][195939] = {name = "[q4]Kühne Prophezeiungshalskette", additional_info = "Wirken in 2.5 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nAuge der Prophezeiung (4), Wutstein , Pandemonit , Infernoschwefel (2), Blut von Sargeras (5)\nOptionale Reagenzien:\n[] (#49)\n[q]Verringert erheblich die erforderlichen Materialien zur Herstellung einer kühnen Prophezeiungshalskette.\nBeute von:\nDargrul\nZone:\nNeltharions Hort (Heroisch)\n\n[q4]Kühne Prophezeiungshalskette\nWird beim Anlegen gebunden\nHals\n+4 Ausdauer\n\n[q0]Prismatischer Sockel\n\nKlassen: Jäger\n[q2]Anlegen: Euer Begleiter verfällt in einen Wutzustand, wenn er Kreaturen aus derselben Familie bekämpft, sodass sich sein Schaden für 10 Sek. um 60% erhöht. Dies kann nur ein Mal alle (150 / 60\n ) Min. auftreten. (2.5Min. Abklingzeit)\n45"}
MultiLanguageSpellData['de'][195940] = {name = "[q4]Uraltes Mahlstromamulett", additional_info = "Wirken in 2.5 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nMahlstromsaphir (4), Wutstein , Pandemonit , Infernoschwefel (2), Blut von Sargeras (5)\nOptionale Reagenzien:\n[] (#49)\n[q]Verringert erheblich die erforderlichen Materialien zur Herstellung eines uralten Mahlstromamuletts.\nVerkäufer:\nRansa Graufeder\nZone:\nDer Hochberg\nHochbergstamm - Ehrfürchtig\nKosten:\n3000\n\n[q4]Uraltes Mahlstromamulett\nWird beim Anlegen gebunden\nHals\n+4 Ausdauer\n\n[q0]Prismatischer Sockel\n\nKlassen: Schamane\n[q2]Anlegen: Regeneriert alle 1 Sek. 27 Gesundheit, während Ihr schwimmt oder im Wasser steht und Euch dabei nicht im Kampf befindet.\n45"}
MultiLanguageSpellData['de'][195941] = {name = "[q4]Rechtschaffenes Morgenlichtmedaillon", additional_info = "Wirken in 2.5 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nMorgenlicht (4), Wutstein , Pandemonit , Infernoschwefel (2), Blut von Sargeras (5)\nOptionale Reagenzien:\n[] (#49)\n[q]Verringert erheblich die erforderlichen Materialien zur Herstellung eines rechtschaffenen Morgenlichtmedaillons.\nBeute von:\nBerater Melandrus\nZone:\nDer Hof der Sterne (Heroisch)\n\n[q4]Rechtschaffenes Morgenlichtmedaillon\nWird beim Anlegen gebunden\nHals\n+4 Ausdauer\n\n[q0]Prismatischer Sockel\n\nKlassen: Paladin\n[q2]Anlegen: Bei einem erlittenen Treffer besteht eine Chance, Euren Gegner für 5 Sek. zu blenden und Euch um 15% verringerten Schaden zufügt. Dieser Effekt kann nur einmal alle 120 Sek. auftreten. (Procchance: 40%, 2Min. Abklingzeit)\n45"}
