MultiLanguageSpellData['de'][196508] = {name = "Gedankenschinden", additional_info = "100 Meter Reichweite\nWirken in 1 sek.\n[q]Fügt einem Gegner im Verlauf von 8 Sek. Schattenschaden zu und verringert die Bewegungsgeschwindigkeit des Ziels um 50%."}
MultiLanguageSpellData['de'][196509] = {name = "Gedankenschinden", additional_info = "100 Meter Reichweite\nKanalisiert (Wirken in 4 sek.)\n[q]Fügt einem Gegner im Verlauf von 4 Sek. Schattenschaden zu. Die Bewegungsgeschwindigkeit des Ziels wird um 0% verringert und das Opfer flieht während der Effektdauer furchterfüllt."}
MultiLanguageSpellData['de'][196512] = {name = "Klauenzorn", additional_info = "{Wirken in} {1 sek. 2 sek. Abklingzeit}\n[q]Fenryr greift wild an und fügt allen Gegnern innerhalb von 12 Metern 20607820 körperlichen Schaden zu, der unter allen Zielen aufgeteilt wird.\n\n Dieser Angriff trifft immer und ignoriert Rüstung."}
MultiLanguageSpellData['de'][196515] = {name = "Magische Bindung", additional_info = "Wirken in 3 sek.\n[q]Macht alle Gegner innerhalb von 60 Metern bewegungsunfähig und fügt ihnen 6 Sek. lang alle 2 Sek. 4653198 Arkanschaden zu."}
MultiLanguageSpellData['de'][196516] = {name = "Blitzgeschoss", additional_info = "40 Meter Reichweite\nWirken in 2.5 sek.\n[q]Fügt einem zufälligen Gegner 4364009 Naturschaden zu."}
MultiLanguageSpellData['de'][196517] = {name = "Wirbelnde Sense", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Wirft eine Sense nach einem Spielercharakter, die allen Spielercharakteren, die sich in ihrem Weg befinden, 7273348 körperlichen Schaden zufügt und sie zurückstößt."}
