MultiLanguageSpellData['de'][198973] = {name = "Schwarzpulverladung", additional_info = "Wirken in 2 sek.\nReagenzien:\nLeysteinerz (2), Übergroße Sprengkapsel (30)\n[q]Stellt eine Schwarzpulverladung her.\nQuest:\nUnkrautvernichter\nZone:\nVal'sharah\n\n(5)\n[q2]Benutzen: Fügt einem Gegner innerhalb von bis zu 40 Metern ( 810 + 485 ) Feuerschaden zu. (5 Min Abklingzeit)\n39"}
