MultiLanguageSpellData['de'][201496] = {name = "Frittierte Mooskieme", additional_info = "Wirken in 2 sek.\nReagenzien:\nMooskiemenbarsch (5), Moschushirschbutter (5)\n[q]Bereitet eine frittierte Mooskieme zu.\nQuest:\nEs hat sich ausgekrächzt\nZone:\nVal'sharah\n\n(5)\n[q2]Benutzen: Stellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 8 Tempo.\n40"}
MultiLanguageSpellData['de'][201497] = {name = "Eingelegter Sturmrochen", additional_info = "Wirken in 2 sek.\nReagenzien:\nSturmrochen (5), Grobes Meersalz (3)\n[q]Bereitet einen eingelegten Sturmrochen zu.\nQuest:\nSchwere Bürde\nZone:\nSturmheim\n\n(5)\n[q2]Benutzen: Stellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 8 Meisterschaft.\n40"}
MultiLanguageSpellData['de'][201498] = {name = "Faronaarsprudel", additional_info = "Wirken in 2 sek.\nReagenzien:\nWildvogelei (5), Flusszwiebel (2), Königliche Olive (3)\n[q]Bereitet Faronaarsprudel zu.\nQuest:\nDer Magister der Mixologie\nZone:\nAzsuna\n\n(5)\n[q2]Benutzen: Stellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 8 Vielseitigkeit.\n40"}
MultiLanguageSpellData['de'][201499] = {name = "Würziger Rippchenbraten", additional_info = "Wirken in 2 sek.\nReagenzien:\nGroße Wildrippchen (5), Dalapeñoschote (5)\n[q]Bereitet einen würzigen Rippchenbraten zu.\nQuest:\nZahltag\nZone:\nSturmheim\nGegenstand:\nSechszünders Vorratskiste\n\n(5)\n[q2]Benutzen: Stellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n\n Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet eine Chance, beim Angreifen eine Salve Pfefferatemfeuerbälle abzufeuern, die jeweils 105 Feuerschaden verursachen. Dieser Effekt hält 1 Stunde lang an.\n40"}
