MultiLanguageSpellData['de'][205021] = {name = "Froststrahl", additional_info = "{2% von Grundmana} {40 Meter Reichweite}\nKanalisiert (Wirken in 5 sek.) 1 min Abklingzeit\n[q]Kanalisiert 5 Sek. lang einen Strahl eisiger Macht auf einen Gegner, der ihm alle 1 Sek. (269.1% der Zaubermacht) Frostschaden zufügt und ihn um 60% verlangsamt. Jedes Mal, wenn 'Froststrahl' Schaden verursacht, werden der Schaden und die Verlangsamung des Effekts um 10 % erhöht.\n\n Erzeugt im Verlauf der Effektdauer 2 Aufladungen von 'Eisige Finger'."}
MultiLanguageSpellData['de'][205022] = {name = "Arkaner Familiar", additional_info = "[q]Das Wirken von 'Arkane Intelligenz' beschwört einen Familiar, der Eure Gegner angreift und Euer maximales Mana 1 Stunde lang um 10% erhöht."}
MultiLanguageSpellData['de'][205023] = {name = "Großbrand", additional_info = "[q]'Feuerball' und 'Pyroschlag' belegen das Ziel mit 'Großbrand', wodurch es im Verlauf von 8 Sek. zusätzlich (7.03868% der Zaubermacht) Feuerschaden erleidet.\n\n Bei Gegnern, die von 'Großbrand' oder 'Entzünden' betroffen sind, besteht eine Chance von 15%, dass sie auflodern und Gegnern in der Nähe (6.28762% der Zaubermacht) Feuerschaden zufügen."}
MultiLanguageSpellData['de'][205024] = {name = "Einsamer Winter", additional_info = "[q]Ersetzt Wasserelementar beschwören\n[q]'Frostblitz', 'Eislanze' und 'Hagel' verursachen 15% mehr Schaden."}
MultiLanguageSpellData['de'][205025] = {name = "Geistesgegenwart", additional_info = "{Sofort} {45 sek. Abklingzeit}\n[q]Macht 2 folgende Einsätze von 'Arkanschlag' zu Spontanzaubern ."}
MultiLanguageSpellData['de'][205026] = {name = "Feuerteufel", additional_info = "[q]Wenn das Ziel mehr als 90% Gesundheit hat, erzielen Eure Zauber 'Feuerball' und 'Pyroschlag' immer einen kritischen Treffer."}
MultiLanguageSpellData['de'][205027] = {name = "Knochenkälte", additional_info = "[q]Immer wenn Ihr versucht, ein Ziel zu unterkühlen, gewinnt Ihr 'Knochenkälte' hinzu, wodurch Euer sämtlicher verursachter Zauberschaden für 8 Sek. um 0.5% erhöht wird. Dieser Effekt ist bis zu 10-mal stapelbar."}
