MultiLanguageSpellData['de'][206930] = {name = "Herzstoß", additional_info = "{1 Rune / -15 Runenmacht} {Nahkampfreichweite}\nSofort\nBenötigt Nahkampfwaffe\n[q]Schlägt das Ziel sowie einen weiteren Gegner in der Nähe sofort, verursacht (57.005% der Angriffskraft) körperlichen Schaden und verringert die Bewegungsgeschwindigkeit der Gegner 8 Sek. lang um 20%. [ Herzstoß : Erzeugt 5 zusätzliche Runenmacht ] [ Herzbrecher : und 2 Runenmacht pro zusätzlich getroffenem Gegner ]."}
MultiLanguageSpellData['de'][206931] = {name = "Bluttrinker", additional_info = "{1 Rune / -10 Runenmacht} {30 Meter Reichweite}\n{Kanalisiert (Wirken in} {3 sek.) 30 sek. Abklingzeit}\n[q]Entzieht dem Ziel im Verlauf von 3 Sek. 9 Gesundheit. Der Euch vom Ziel zugefügte Schaden wird während der Dauer und 5 Sek. nach vollständiger Kanalisierung 15% verringert.\n\n Ihr könnt Euch bewegen, parieren, ausweichen und defensive Fähigkeiten einsetzen, während Ihr diese Fähigkeit kanalisiert.\n\nErzeugt während der Dauer 20 zusätzliche Runenmacht."}
MultiLanguageSpellData['de'][206932] = {name = "Arkane Rüstung", additional_info = "Sofort\n[q]Diese kleinen arkanen Schrubber sind beinahe unzerstörbar und fügen Gegnern in der Nähe 2953 Arkanschaden zu, während sie fleißig ihrer Arbeit nachgehen.\n Würde jemand allerdings die Ansaugstutze eines Schrubbers verstopfen, würde dies zu katastrophalen Ergebnissen führen."}
MultiLanguageSpellData['de'][206935] = {name = "Blutige Vergeltung", additional_info = "Sofort 1.5 min Abklingzeit\n[q]Während dieser Effekt aktiv ist, werden Gegner, die den Todesritter mit Nahkampffähigkeiten treffen, mit der Blutseuche infiziert. Ist der Gegner bereits infiziert, verursacht die Blutseuche ihren Schaden sofort 3-mal. 6 Aufladungen. Hält 15 Sek. lang an.\n(1s Abklingzeit)"}
