MultiLanguageSpellData['de'][206984] = {name = "Wilde Teufelsbrut", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Manifestiert wilde Teufelsbruten in der Nähe, von denen jede ihrem Meister regelmäßig einen Schild gewährt und seinen erlittenen Schaden so für 7 Sek. um 30% verringert."}
MultiLanguageSpellData['de'][206985] = {name = "Streuungsfeld", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Das aktive Auge von Aman'thul kondensiert große Macht zu einer schützenden Kuppel, die 100% des erlittenen Feuerschadens bis zu maximal 109954 Schaden absorbiert. Die Absorption verteilt sich auf alle Verbündeten innerhalb von 10 Metern."}
MultiLanguageSpellData['de'][206986] = {name = "Seelenschnitter", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Stößt auf das aktuelle Ziel hinab, trifft es mit 1568 körperlichem Schaden und erzeugt mehrere Schattenmagiebögen, die sich nach außen bewegen. Jeder Bogen schert ein Stück der Seele jedes getroffenen Ziels von seinem Körper ab und stößt dieses Stück auf den Kampfplatz aus. ' Abgeschorene Seele ' absorbiert die gesamte erhaltene Heilung, bis ein anderer Spielercharakter das Stück einsammelt.\n\n Wenn die ' Abgeschorene Seele ' eingesammelt wird, fügt sie Zielen innerhalb von 2 Metern 140 Schattenschaden zu, belegt sie mit ' Abgetrennt ' und erhöht den durch ' Abgetrennt ' erlittenen Schaden um 900 %.\n\n Sobald das Ziel sein Seelenfragment zurückbekommt, wird es zusätzlich mit ' Abgetrennte Seele ' belegt, wodurch 896 erhaltene Heilung absorbiert wird."}
