MultiLanguageSpellData['de'][207142] = {name = "Lawine", additional_info = "[q]Während Euer 'Raureif' aktiv ist, fallen bei jedem Einsatz von 'Heulende Böe' zusätzlich gezackte Eiszapfen auf Gegner in der Nähe Eures Ziels herab, die sie mit 'Schneidendes Eis' belegen und ihnen (22.47% der Angriffskraft) Frostschaden zufügen."}
MultiLanguageSpellData['de'][207143] = {name = "Leerenausstoß", additional_info = "Sofort\n[q]Leerenenergie manifestiert sich und fliegt auf Spielercharaktere zu, um sofort 2566 Schattenschaden sowie nach 8 Sek. 2566 Schattenschaden zu verursachen. Zusätzlich bricht nach 8 Sek. eine 'Leereneruption' aus betroffenen Spielercharakteren hervor."}
MultiLanguageSpellData['de'][207144] = {name = "In die Enge treiben", additional_info = "{50 Fokus} {100 Meter Reichweite}\n{Sofort} {16 sek. Abklingzeit}\n[q]Befiehlt Eurem Tier, das Ziel anzugreifen und so [1.5 * (0 + (Fernkampfangriffskraft * 1.632)) * 1 * (1 + Vielseitigkeit)] Schaden zu verursachen. Wenn das Ziel bewegungsunfähig ist, verursacht 'In die Enge treiben' 200% zusätzlichen Schaden und die Bewegungsgeschwindigkeit des Ziels wird 3 Sek. lang um 70% verringert."}
