MultiLanguageSpellData['de'][207217] = {name = "Anhänger: Taran Zhu", additional_info = "Sofort\n[q]Taran Zhu ist der fähige Kämpfer und furchtlose Anführer der Shado-Pan, einem Orden, der sich dem Schutz von Pandaria vor dem Sha gewidmet hat."}
MultiLanguageSpellData['de'][207218] = {name = "Artefakt zerstören: Titanenblitz", additional_info = nil}
MultiLanguageSpellData['de'][207219] = {name = "Anhänger: Der Affenkönig", additional_info = "Sofort\n[q]Der Affenkönig war der zuverlässige Begleiter von Shaohao, Kaiser von ganz Pandaria. Er ist gewitzt und schelmisch und weiß von ungeahnten Geheimnissen aus der Vergangenheit Pandarias."}
MultiLanguageSpellData['de'][207220] = {name = "Anhänger: Angus Eisenfaust", additional_info = "Sofort\n[q]Angus Eisenfaust war von jüngster Kindheit an von Kampfeswillen durchdrungen. Er liebt es, sich mit dem Gegner von Angesicht zu Angesicht wiederzufinden, und bezwingt ihn mit einer Kombination aus Kampfkunst, Grifftechniken, Ringen und gut abgepassten Schlägen und Tritten."}
MultiLanguageSpellData['de'][207221] = {name = "Schlafen", additional_info = nil}
MultiLanguageSpellData['de'][207222] = {name = "Anhänger: Hiro", additional_info = "Sofort\n[q]Hiro hat lange Zeit die Welt durchwandert, ziellos eine Taverne nach der anderen auf der Suche nach dem nächsten Getränk durchstreift. Lasst Euch nicht von seinem abgerissenen Äußeren verwirren. Er hat nicht nur ein Herz aus Gold, sondern wird mit jedem Getränk auch zu einem noch besseren Kämpfer."}
MultiLanguageSpellData['de'][207223] = {name = "Anhängerin: Sylara Stahlsang", additional_info = "Sofort\n[q]Sylara Schattenherz ist eine geheimnisvolle Wanderin, die selten über ihre Vergangenheit spricht. Eins ist jedoch klar: Nichts macht sie wütender als Ungerechtigkeit. Jeder, der sich ihr in den Weg stellt, bekommt ihre Zwillingsklingen zu spüren."}
MultiLanguageSpellData['de'][207224] = {name = "Quest Credit", additional_info = nil}
MultiLanguageSpellData['de'][207225] = {name = "Anhängerin: Aegira", additional_info = "Sofort\n[q]Aegira ist eine Braumeisterin der Vrykul, die in der Gunst Odyns steht. Ihre Braukunst ist legendär. Nur wenige wissen, dass ihre Kampfkunst ihr in nichts nachsteht. Sie wuchs auf dem Schlachtfeld auf und ist bisher ungeschlagen."}
