MultiLanguageSpellData['de'][207228] = {name = "Nachtbrunnen verzerren", additional_info = "500 Meter Reichweite\nWirken in 4 sek.\n[q]Der Zaubernde verzerrt den Nachtbrunnen und fügt allen Spielercharakteren 733 Arkanschaden zu.\n\n Jeder Einsatz dieses Zaubers erhöht den Schaden weiterer Verzerrungen des Zaubernden um 20%."}
MultiLanguageSpellData['de'][207229] = {name = "Keuchen der Auslöschung", additional_info = "100 Meter Reichweite\nWirken in 2.5 sek.\n[q]Fügt allen Zielen in einem kegelförmigen Bereich vor dem Zaubernden Schattenschaden zu."}
MultiLanguageSpellData['de'][207230] = {name = "Frostsichel", additional_info = "2 Runen 8 Meter Reichweite\nSofort\n[q]Ein weitreichender Angriff, der allen Gegnern vor Euch (40% der Angriffskraft) Frostschaden zufügt. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu.\n\n Verbraucht 'Tötungsmaschine', damit kritische Treffer 4-mal mehr als den üblichen Schaden verursachen."}
