MultiLanguageSpellData['de'][207234] = {name = "Nachtbrunnen verzerren", additional_info = "500 Meter Reichweite\nKanalisiert (Wirken in 2 sek.)\n[q]Der Zaubernde verzerrt den Nachtbrunnen und fügt allen Spielercharakteren 733 Arkanschaden zu.\n\n Jeder Einsatz dieses Zaubers erhöht den Schaden weiterer Verzerrungen des Zaubernden um 20%."}
MultiLanguageSpellData['de'][207235] = {name = "Anhänger: Celestos", additional_info = "Sofort\n[q]Konsul Celestos ist einer der ältesten und ehrwürdigsten Elementare des Himmelswalls.\n\n Unter Al'Akirs Herrschaft war Celestos der Hauptberater und Taktiker bei vielen Feldzügen des Windlords."}
MultiLanguageSpellData['de'][207236] = {name = "Anhänger: Nobundo", additional_info = "Sofort\n[q]Scharfseher Nobundo ist ein ehemaliger Paladin, der als Erster seines Volkes zum Schamanen wurde und die Elemente studierte.\n\n Er ist einer der weisesten und mächtigsten Schamanen des Irdenen Rings und war ehemals dessen Anführer."}
MultiLanguageSpellData['de'][207237] = {name = "Anhänger: Rehgar Erdenwut", additional_info = "Sofort\n[q]Rehgar Erdenwut ist ein mächtiger Elementarschamane und ein ehemaliger Gladiator, der die Kunst des Kampfes gemeistert hat.0$bDer Irdene Ring hat nur wenige Anhänger, die über Rehgars Erfahrung und Können auf dem Schlachtfeld verfügen."}
MultiLanguageSpellData['de'][207238] = {name = "Anhänger: Scaldius", additional_info = "Sofort\n[q]Baron Scaldius war ehemals Leutnant von Ragnaros und dient nun dem Feuerlord Glimmeron mit unerschütterlicher Ergebenheit.0$bBaron Scaldius befiehlt die Macht und den Zorn der Feuerlande, um jeden einzelnen Gegner niederzustrecken, der ihm über den Weg läuft."}
MultiLanguageSpellData['de'][207239] = {name = "Anhänger: Lavinius", additional_info = "Sofort\n[q]Als einer der großen Steinlords von Tiefenheim ist Lavinius bekanntlich praktisch unverwüstlich.0$bLavinius ignoriert Empfindungen der Sterblichen wie Furcht und Schmerz und erfüllt den Willen seines Meisters mit eiserner Konzentration."}
MultiLanguageSpellData['de'][207240] = {name = "Anhänger: Muln Erdenwut", additional_info = "Sofort\n[q]Muln Erdenwut ist ein ehemaliger Anführer des Irdenen Rings und gehört zu den bedeutendsten Schamanen seiner Generation.0$bSeine beeindruckende Ausstrahlung auf dem Schlachtfeld und seine Meisterschaft des \"traditionellen\" Schamanismus machen ihn zu einem wertvollen Verbündeten."}
