MultiLanguageSpellData['de'][213252] = {name = "Transmutieren: Stoff zu Kräutern", additional_info = "Wirken in 3 sek. 1 tag Abklingzeit\nReagenzien:\nShal'doreiseide (10)\n[q]Transmutiert Stoff der Verheerten Inseln zu Kräutern.\nBeruf:\nAlchemie der Verheerten Inseln\nEntdeckung:\nWilde Transmutation\n\nKräuterhaufen\nWird beim Aufheben gebunden\n[q]\"Ein Haufen Kräuter von den Verheerten Inseln. Kann auch schwarzes Transmutagen enthalten.\"\n[q2]<Zum Öffnen rechtsklicken>"}
