MultiLanguageSpellData['de'][213254] = {name = "Transmutieren: Fisch zu Edelsteinen", additional_info = "Wirken in 3 sek. 1 tag Abklingzeit\nReagenzien:\nVerfluchter Königinnenfisch (5), Mooskiemenbarsch (5), Hochberglachs (5), Sturmrochen (5), Runenschuppenkoi (5), Schwarzer Barrakuda (5)\n[q]Transmutiert Fische der Verheerten Inseln zu Edelsteinen.\nBeruf:\nAlchemie der Verheerten Inseln\nEntdeckung:\nWilde Transmutation\n\nHaufen Juwelen\nWird beim Aufheben gebunden\n[q]\"Ein Haufen Edelsteine. Kann auch öliges Transmutagen enthalten.\"\n[q2]<Zum Öffnen rechtsklicken>"}
MultiLanguageSpellData['de'][213255] = {name = "Transmutieren: Fleisch zu Hosen", additional_info = "Wirken in 3 sek. 1 tag Abklingzeit\nReagenzien:\nMagere Haxe (5), Fettiges Bärensteak (5), Große Wildrippchen (5), Leyblut (5), Wildvogelei (5)\n[q]Transmutiert Fleisch der Verheerten Inseln zu Hosen.\nBeruf:\nAlchemie der Verheerten Inseln\nEntdeckung:\nWilde Transmutation\n\nHaufen Hosen\nWird beim Aufheben gebunden\n[q]\"Ein Haufen Hosen. Kann auch öliges Transmutagen enthalten.\"\n[q2]<Zum Öffnen rechtsklicken>"}
MultiLanguageSpellData['de'][213256] = {name = "[q2]Transmutieren: Fleisch zu Begleiter", additional_info = "Wirken in 3 sek. 1 tag Abklingzeit\nReagenzien:\nFettiges Bärensteak (3), Intakte Kralle (20), Intakter Zahn (20), Zähflüssiges Transmutagen , Schwarzes Transmutagen , Öliges Transmutagen\n[q]Transmutiert Fleisch der Verheerten Inseln zu einem Begleiter.\nBeruf:\nAlchemie der Verheerten Inseln\nEntdeckung:\nWilde Transmutation\n\n[q2]Pulsierender Sack\nWird beim Aufheben gebunden\nEinzigartig\nDauer: 7 tagen (Realzeit)\n[q]\"Eine zuckende Masse aus transmutiertem Fleisch.\""}
MultiLanguageSpellData['de'][213257] = {name = "[q3]Transmutieren: Blut von Sargeras", additional_info = "Wirken in 3 sek. 1 tag Abklingzeit\nReagenzien:\nSchwarzes Transmutagen (5), Zähflüssiges Transmutagen (4), Öliges Transmutagen (3)\n[q]Transmutiert Transmutagene der Verheerten Inseln zu Blut von Sargeras.\nBeruf:\nAlchemie der Verheerten Inseln\nEntdeckung:\nWilde Transmutation\n\n[q3]Blut von Sargeras\nWird beim Aufheben gebunden\nHandwerksmaterial"}
