MultiLanguageSpellData['de'][215116] = {name = "Champion: Akamas Schemen", additional_info = "Sofort\n[q]Als Meisterarchitekt von Illidans Plan zur Zerstörung der Brennenden Legion und Oberhaupt der Aschenzungen hat sich Akama sowohl als fähiger Anführer als auch als brillanter Stratege und geübter Kämpfer erwiesen. Sein Schemen ist all dies und mehr."}
MultiLanguageSpellData['de'][215117] = {name = "Champion: Matronenmutter Malicia", additional_info = "Sofort\n[q]Malicia hat sich immer wieder als Verbündete von unschätzbarem Wert erwiesen. Es gilt als absolut sicher, dass Ihr ohne sie nicht hier stehen würdet. Ihre Fähigkeiten als Anführerin werden nur von ihrer meisterhaften Beherrschung dämonischer Magie in den Schatten gestellt."}
