MultiLanguageSpellData['de'][215128] = {name = "Verfluchtes Blut", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Infiziert das Blut von Spielercharakteren mit Alptraumenergie, die ihnen 8 Sek. lang alle 2 Sek. 865 Schattenschaden zufügt. Wenn dieser Effekt endet, detoniert der Spielercharakter und fügt allen Spielercharakteren innerhalb von 11 Metern 3959 Schattenschaden zu."}
MultiLanguageSpellData['de'][215129] = {name = "Champion: Altruis der Leidende", additional_info = "Sofort\n[q]Als niemand sonst Illidans Methode kritisierte, die Brennende Legion ungeachtet aller Opfer zu bekämpfen, war da Altruis. Er ist so stark, wie ein Dämonenjäger nur sein kann, und seine Kampfkraft wird nur von seinem scharfen Intellekt und dem Respekt übertrumpft, den er sich mit seinem Einsatz dafür verschafft hat, die Methoden der Illidari zu verändern."}
MultiLanguageSpellData['de'][215131] = {name = "Schnelligkeitszone", additional_info = "{Sofort} {5 sek. Abklingzeit}\n[q]Beschwört ein Feld aus arkaner Energie, die das Tempo aller Einheiten im Feld um 50% erhöht."}
