MultiLanguageSpellData['de'][215133] = {name = "Champion: Kayn Sonnenzorn", additional_info = "Sofort\n[q]Kayn war durchgehend der unbezwingbare Fels in der Brandung. Wo andere begannen, Illidans Methoden zu hinterfragen, stand Kayn zu dessen Kurs und drängte darauf, dass einzig die Zerstörung der Brennenden Legion von wahrer Bedeutung sei. Er ist ein starker Kämpfer, geübter Taktiker und beispielloser Politiker."}
